103	// ---------------------------------------------------------------------------
104	// Loading helper
105	// ---------------------------------------------------------------------------
106	
107	/**
108	 * Render a loading spinner into `el`.
109	 *
110	 * @param {HTMLElement} el
111	 * @param {string} [label]
112	 */
113	function showLoading(el, label = 'Loading…') {
114	    el.innerHTML = '';
115	    const wrapper = document.createElement('div');
116	    wrapper.className = 'loading-indicator';
117	    wrapper.setAttribute('aria-live', 'polite');
118	
119	    const spinner = document.createElement('span');
120	    spinner.className = 'spinner';
121	    spinner.setAttribute('aria-hidden', 'true');
122	    wrapper.appendChild(spinner);
123	
124	    const labelEl = document.createElement('span');
125	    labelEl.textContent = label;
126	    wrapper.appendChild(labelEl);
127	
128	    el.appendChild(wrapper);
129	}
130	
131	// ---------------------------------------------------------------------------
132	// Setup helper
133	// ---------------------------------------------------------------------------
134	
135	/**
136	 * Run workspace setup and show appropriate toast notification.
137	 *
138	 * @param {string} projectId
139	 * @param {string} workspaceId
140	 * @param {string} successMessage - Toast message shown when all repos succeed.
141	 * @returns {Promise<Object>} The setup result from the API.
142	 * @throws {Error} Re-throws API errors for the caller to handle.
143	 */
144	async function runSetup(projectId, workspaceId, successMessage) {
145	    const result = await api.workspaces.setup(projectId, workspaceId);
146	    const failures = (result && result.results || []).filter((r) => !r.success);
147	    if (failures.length > 0) {
148	        const names = failures.map((f) => f.repositoryId).join(', ');
149	        showToast(`Setup complete with errors. Failed to clone: ${names}`, 'warning', 8000);
150	    } else {
151	        showToast(successMessage, 'success');
152	    }
153	    return result;
154	}
155	
156	// ---------------------------------------------------------------------------
157	// Status table helpers
158	// ---------------------------------------------------------------------------
159	
160	/**
161	 * Build the status `<tbody>` row for a single repository.
162	 *
163	 * The row uses `data-repo-id` on the badge container so the polling update
164	 * can locate and replace badge contents in-place.
165	 *
166	 * @param {Object} opts
167	 * @param {string} opts.repoId      - Unique repository identifier (e.g. `"my-repo"`).
168	 * @param {string} opts.repoName    - Human-readable display name; falls back to
169	 *                                    `repoId` when no name is available.
170	 * @param {Object|null} opts.statusInfo - GitStatusInfo object from the API, or
171	 *                                    `null` when status data is not yet available.
172	 * @param {string} opts.projectId   - ID of the parent project.
173	 * @param {string} opts.wid         - ID of the parent workspace.
174	 * @param {boolean} [opts.isStable] - When `true`, the branch cell is rendered as
175	 *                                    plain text (no clickable trigger).
176	 * @param {function(HTMLElement, string, string): void} [opts.onBranchCellClick]
177	 *                                  - Callback invoked with `(anchorEl, repoId,
178	 *                                    currentBranch)` when the branch cell trigger is
179	 *                                    clicked. Only wired when `!isStable`.
180	 * @param {string|null} [opts.webserverUrl] - Base URL of the local webserver. When
181	 *                                    truthy, a "Browse" button is prepended before
182	 *                                    the "Git GUI" button.
183	 * @returns {HTMLTableRowElement}
184	 */
185	function buildRepoStatusRow({ repoId, repoName, statusInfo, projectId, wid, isStable, onBranchCellClick, webserverUrl }) {
186	    const tr = document.createElement('tr');
187	    tr.dataset.repoId   = repoId;
188	    tr.dataset.repoName = repoName;
189	
190	    // Repository name / ID
191	    const nameCell = document.createElement('td');
192	    nameCell.className = 'repo-name-cell';
193	    const nameEl = document.createElement('span');
194	    nameEl.className = 'repo-name';
195	    nameEl.textContent = repoName;
196	    if (repoName !== repoId) {
197	        const idHint = document.createElement('span');
198	        idHint.className = 'text-muted repo-id-hint';
199	        idHint.textContent = ` (${repoId})`;
200	        nameEl.appendChild(idHint);
201	    }
202	    nameCell.appendChild(nameEl);
203	    tr.appendChild(nameCell);
204	
205	    // Branch, badge, and actions cells — delegated to shared component.
206	    const { branchCell, badgeCell, actionsCell } = buildRepoStatusCells({
207	        repoId,
208	        repoName,
209	        statusInfo,
210	        projectId,
211	        wid,
212	        isStable,
213	        onBranchCellClick,
214	        webserverUrl,
215	    });
216	    tr.appendChild(branchCell);
217	    tr.appendChild(badgeCell);
218	    tr.appendChild(actionsCell);
219	
220	    return tr;
221	}
222	
223	/**
224	 * Update an existing status table in-place by replacing badge contents and
225	 * branch text for each repository whose status has changed.
226	 *
227	 * Rows are located via `[data-repo-id]` on both the `<tr>` and the badge
228	 * wrapper `<div>` inside it. No full re-render of the table is performed.
229	 *
230	 * @param {HTMLElement}           tableBody - The `<tbody>` to update.
231	 * @param {Record<string, Object|null>} statusMap - Keyed by repository ID.
232	 * @param {boolean} [isStable] - When `true`, branch cells are rebuilt as plain text.
233	 * @param {function(HTMLElement, string, string): void} [onBranchCellClick]
234	 *   Wired to the branch trigger button in non-STABLE workspaces.
235	 */
236	function updateStatusTable(tableBody, statusMap, isStable, onBranchCellClick) {
237	    for (const [repoId, statusInfo] of Object.entries(statusMap)) {
238	        const row = tableBody.querySelector(`tr[data-repo-id="${CSS.escape(repoId)}"]`);
239	        if (!row) continue;
240	        updateRepoStatusCells(row, repoId, statusInfo, isStable, onBranchCellClick);
241	    }
242	}
243	
244	// ---------------------------------------------------------------------------
245	// Section builders
246	// ---------------------------------------------------------------------------
247	
248	/**
249	 * Build the rename workspace inline form and wire up its event handlers.
250	 *
251	 * @param {string} projectId
252	 * @param {{ id: string }} workspace
253	 * @param {HTMLButtonElement} renameBtn - The "Rename" button that toggles form visibility.
254	 * @returns {HTMLElement}
255	 */
256	function buildRenameForm(projectId, workspace, renameBtn) {
257	    const wrapper = document.createElement('div');
258	    wrapper.className = 'rename-workspace-form-wrapper card';
259	    wrapper.hidden = true;
260	
261	    const formTitle = document.createElement('h4');
262	    formTitle.className   = 'form-section-title';
263	    formTitle.textContent = 'Rename Workspace';
264	    wrapper.appendChild(formTitle);
265	
266	    const newIdField = createFormField('New Workspace ID', 'text', 'newWorkspaceId', {
267	        required:    true,
268	        placeholder: 'e.g. DEV or FEATURE',
269	        hint:        'Must be 2–10 uppercase letters (A-Z only).',
270	    });
271	    wrapper.appendChild(newIdField);
272	
273	    const newIdInput   = newIdField.querySelector('[name="newWorkspaceId"]');
274	    const newIdErrorEl = newIdField.querySelector('.field-error');
275	
276	    const formActions = document.createElement('div');
277	    formActions.className = 'form-actions';
278	
279	    const saveBtn = document.createElement('button');
280	    saveBtn.type      = 'button';
281	    saveBtn.className = 'btn btn-primary btn-sm';
282	    saveBtn.textContent = 'Save';
283	
284	    const cancelFormBtn = document.createElement('button');
285	    cancelFormBtn.type      = 'button';
286	    cancelFormBtn.className = 'btn btn-secondary btn-sm';
287	    cancelFormBtn.textContent = 'Cancel';
288	
289	    formActions.appendChild(saveBtn);
290	    formActions.appendChild(cancelFormBtn);
291	    wrapper.appendChild(formActions);
292	
293	    // Behaviour
294	    renameBtn.addEventListener('click', () => {
295	        wrapper.hidden = false;
296	        if (newIdInput) newIdInput.focus();
297	    });
298	
299	    cancelFormBtn.addEventListener('click', () => {
300	        wrapper.hidden = true;

101	    badgeWrapper.appendChild(createStatusBadge(statusInfo || null));
102	    badgeCell.appendChild(badgeWrapper);
103	
104	    // ------------------------------------------------------------------
105	    // Actions cell — "Git GUI" button (always present) + optional "Browse"
106	    // ------------------------------------------------------------------
107	    const actionsCell = document.createElement('td');
108	    actionsCell.className = 'repo-actions-cell';
109	
110	    const openBtn = document.createElement('button');
111	    openBtn.type        = 'button';
112	    openBtn.className   = 'btn btn-secondary btn-sm';
113	    openBtn.textContent = 'Git GUI';
114	    openBtn.title       = 'Open this repository in GitHub Desktop.';
115	
116	    openBtn.addEventListener('click', async () => {
117	        openBtn.disabled    = true;
118	        openBtn.textContent = 'Opening…';
119	        try {
120	            await api.workspaces.launch.githubDesktop(projectId, wid, repoId);
121	        } catch (err) {
122	            // Import showToast lazily to avoid a hard dependency cycle; callers
123	            // that need richer error UX can wrap this function.
124	            const { showToast } = await import('./toast.js');
125	            showToast(err.message || 'Failed to open GitHub Desktop.', 'error');
126	        } finally {
127	            openBtn.disabled    = false;
128	            openBtn.textContent = 'Git GUI';
129	        }
130	    });
131	
132	    actionsCell.appendChild(openBtn);
133	
134	    // Browse button — shown only when webserverUrl is configured.
135	    if (webserverUrl) {
136	        const browseBtn = document.createElement('button');
137	        browseBtn.type        = 'button';
138	        browseBtn.className   = 'btn btn-secondary btn-sm';
139	        browseBtn.textContent = 'Browse';
140	        browseBtn.title       = 'Open this repository in the browser via the configured webserver URL.';
141	
142	        browseBtn.addEventListener('click', () => {
143	            const url = `${webserverUrl}/${encodeURIComponent(projectId)}/${encodeURIComponent(wid)}/${encodeURIComponent(repoId)}/`;
144	            window.open(url, '_blank');
145	        });
146	
147	        // Insert Browse before Git GUI so the visual order is: Browse → Git GUI.
