769	/**
770	 * Render the workspace detail view.
771	 *
772	 * Fetches workspace metadata, project (for the repositories list), polling
773	 * configuration, and initial Git status in parallel. Then starts a polling
774	 * interval that updates badges in-place using the server-configured interval
775	 * (falls back to {@link DEFAULT_POLL_INTERVAL_MS} if the config fetch fails).
776	 *
777	 * @param {HTMLElement} container - The `#app` DOM element provided by the router.
778	 * @param {{ id: string, wid: string }} params - Route parameters.
779	 * @returns {function(): void} Cleanup function — clears the polling interval.
780	 *   The router stores and calls this before rendering the next view.
781	 */
782	export function renderWorkspaceDetail(container, params) {
783	    const projectId = params.id;
784	    const wid       = params.wid;
785	
786	    let countdownInterval = null;
787	
788	    // Return the cleanup function immediately so the router can register it
789	    // even if the async bootstrap hasn't resolved yet.
790	    const cleanup = () => {
791	        if (countdownInterval !== null) {
792	            clearInterval(countdownInterval);
793	            countdownInterval = null;
794	        }
795	    };
796	
797	    // Show loading state immediately.
798	    showLoading(container, 'Loading workspace…');
799	
800	    // Kick off parallel data fetch.
801	    Promise.all([
802	        api.workspaces.get(projectId, wid),
803	        api.projects.get(projectId),
804	        api.status.refresh(projectId, wid).catch(() => null),
805	        api.config.polling.get().catch(() => null),
806	        api.workspaces.health(projectId, wid).catch(() => null),
807	        api.config.webserverUrl.get().catch(() => null),
808	    ]).then((results) => {
809	        const [rawWorkspace, rawProject, statusMap, pollingConfig, healthReport, webserverUrlConfig] = results;
810	        // Guard: if the container was cleared by navigation before we resolved,
811	        // do nothing and let the cleanup function handle the interval.
812	        if (!container.isConnected) return;
813	
814	        const workspace = normaliseWorkspace(rawWorkspace);
815	        const project   = normaliseProject(rawProject);
816	
817	        // Build repo list: [{ repoId, repoName }, …]
818	        const repos = project.repositories.map((r) => ({
819	            repoId:   extractRepoId(r),
820	            repoName: extractRepoName(r),
821	        })).filter((r) => r.repoId !== '');
822	
823	        // Render the view.
824	        container.innerHTML = '';
825	
826	        const isStable = wid === STABLE_WS_ID;
827	
828	        // Resolve the effective poll interval from server config, with fallback.
829	        const pollIntervalMs = (
830	            pollingConfig &&
831	            typeof pollingConfig.gitPollingIntervalSeconds === 'number' &&
832	            Number.isFinite(pollingConfig.gitPollingIntervalSeconds) &&
833	            pollingConfig.gitPollingIntervalSeconds > 0
834	        )
835	            ? pollingConfig.gitPollingIntervalSeconds * 1000
836	            : DEFAULT_POLL_INTERVAL_MS;
837	
838	        // Resolve webserver URL (null when not configured or fetch failed).
839	        const webserverUrl = (
840	            webserverUrlConfig &&
841	            typeof webserverUrlConfig.webserverUrl === 'string' &&
842	            webserverUrlConfig.webserverUrl !== ''
843	        )
844	            ? webserverUrlConfig.webserverUrl
845	            : null;
846	
847	        // Build status table first to obtain tbody reference for helpers.
848	        const { section: statusSection, tbody } = buildStatusTableSection(repos, statusMap || {}, projectId, wid, isStable, onBranchCellClick, webserverUrl);
849	
850	        // -------------------------------------------------------------------
851	        // Refresh helpers (referenced by toolbar, polling, and setup)
852	        // -------------------------------------------------------------------
853	
854	        let remainingSeconds = pollIntervalMs / 1000;
855	        let refreshInProgress = false;
856	
